import {e,icon,btn,link,Header,number,money,EmptyState} from './components.js';
import {overview,formatMinor,receiptCandidates,DEMO_TODAY} from './daily-demo.js';
const titles={expense:'Добавить расход',payment:'Записать платёж',obligation:'Добавить обязательство',harvest:'Записать срез',depot:'Добавить чек депо','inventory-arrival':'Приход на склад','inventory-consumption':'Внесение удобрения','inventory-transfer':'Перемещение',task:'Задача себе',worker:'Задача работникам'};
export const actionTitle=kind=>titles[kind]||'Связать срез и чек';
const label=(name,title,value='',extra='')=>`<label class="field">${e(title)}<input class="input" name="${e(name)}" data-testid="daily-${e(name)}" value="${e(value)}" ${extra}></label>`;
const select=(name,title,options,value='',empty='Выберите')=>`<label class="field">${e(title)}<select class="input" name="${e(name)}" data-testid="daily-${e(name)}">${empty!=null?`<option value="">${empty}</option>`:''}${options.map(([id,text])=>`<option value="${e(id)}" ${id===value?'selected':''}>${e(text)}</option>`).join('')}</select></label>`;
const fact=(title,value)=>`<div class="fact-row"><dt>${e(title)}</dt><dd>${e(value)}</dd></div>`;
const gh=(s,id)=>s.daily.greenhouses.find(g=>g.id===id)?.name||'Смешанная партия / UNKNOWN';
const minor=x=>x==null?'UNKNOWN':formatMinor(x);
export function contextualActions(primary,secondary=[]){return `<div class="context-actions">${primary.map(([title,to,test])=>link(title,to,'btn secondary',test)).join('')}</div>${secondary.length?`<div class="context-secondary">${secondary.map(([title,to,test])=>link(`${e(title)} ${icon('arrow')}`,to,'',test)).join('')}</div>`:''}`;}
export function financeOverview(s){
 const m=overview(s);
 const cell=(label,value,caption='',cls='')=>`<div class="overview-cell ${cls}"><span>${label}</span><strong>${value==null?'Не рассчитан':number(value/100,2)}</strong><small>${value==null?caption:`TRY${caption?' · '+caption:''}`}</small></div>`;
 return `<section class="card finance-overview" data-testid="finance-overview"><div class="card-header"><h2>Обзор предприятия</h2><span class="tag amber">Неполные данные</span></div><div class="overview-period"><span>1 сентября — 9 октября 2026</span><span>· TRY · Synthetic DEMO</span></div><div class="overview-grid">${cell('Выручка',m.revenueMinor,'подтверждённые продажи')}${cell('Операционные расходы',m.operatingExpenseMinor,'учтённая часть')}${cell('Операционный результат',null,'Недостаточно данных о расходах и оценке запасов','result')}${cell('Денежные поступления',m.cashReceivedMinor,'отдельные платежи')}${cell('Денежные выплаты',m.cashPaidMinor,'включая авансы и тело займа')}${cell('Дебиторская задолженность',m.receivableMinor,'на 9 октября')}${cell('Кредиторская задолженность',m.payableMinor,'на 9 октября')}</div><p class="overview-footnote">Продажа не равна получению денег. Расход не равен выплате. Тело займа не входит в операционные расходы. Остаток денег не рассчитан: начальный баланс UNKNOWN.</p><details class="source-details"><summary>Полнота и основания расчёта</summary><p>Только ${m.sourceCount} синтетических источников. Это демонстрационный набор, не полный учёт хозяйства. Учтённая выручка минус учтённые расходы: ${minor(m.recordedOperatingResultMinor??m.revenueMinor-m.operatingExpenseMinor)}. Это промежуточная разница, не прибыль предприятия.</p><p>Выплаты подтверждены в синтетических сообщениях владельца; сверка банковской выписки не заявляется. Оплата поставки не повторяет расход; накладная не подтверждает физический приход.</p></details></section>`;
}
export function quickForm(s,kind,editId){
 const action=editId?s.daily.actions.find(a=>a.id===editId):null;
 const d=action?{...action.input,...s.dailyDrafts?.[editId]}:s.dailyDrafts?.[kind]||{};
 const key=editId||kind, date=d.date||DEMO_TODAY, currency=d.currency||'TRY';
 let fields='';
 if(['expense','payment','obligation'].includes(kind)){
  fields=`${kind==='expense'?`<label class="field">Исходное сообщение · можно сохранить без уточнений<textarea class="input" name="raw" data-testid="daily-raw" placeholder="Например: Инструменты 7000 лир">${e(d.raw||'')}</textarea></label>`:''}${label('purpose',kind==='expense'?'Назначение расхода':'Назначение',d.purpose)}<div class="form-pair">${label('amount','Сумма',d.amount,'inputmode="decimal" placeholder="0,00"')}${select('currency','Валюта',[['TRY','TRY'],['USD','USD'],['EUR','EUR']],currency,null)}</div>`;
  if(kind==='expense')fields+=`<details class="source-details"><summary>Контрагент · необязательно</summary>${label('party','Кто получил / поставщик',d.party)}</details><p class="note">Отсутствие контрагента не мешает сохранить расход. Оплата и долг этим действием не создаются.</p>`;
  if(kind==='obligation')fields+=select('direction','Направление',[['payable','Я должен'],['receivable','Мне должны']],d.direction||'payable',null)+label('party','Кредитор / дебитор',d.party)+`<p class="note">Обязательство само по себе не является оплатой или новым расходом.</p>`;
  if(kind==='payment')fields+=select('direction','Направление',[['out','Денежная выплата'],['in','Денежное поступление']],d.direction||'out',null)+select('accountId','Денежный счёт · выберите явно',s.daily.accounts.map(a=>[a.id,a.name]),d.accountId)+select('category','Смысл платежа',[['operating','Оплата расхода'],['advance','Аванс'],['loan-principal','Тело займа'],['unclassified','Нужно уточнить']],d.category)+select('obligationId','Погашение конкретного долга',s.daily.obligations.map(o=>[o.id,`${o.party} · ${o.purpose}`]),d.obligationId,'Без связи с долгом')+label('party','Контрагент · если известен',d.party)+`<p class="note">Платёж меняет деньги. Долг уменьшается только при явно выбранной связи. Нового расхода не создаётся.</p>`;
 }
 if(kind==='harvest')fields=select('greenhouseId','Теплица',s.daily.greenhouses.map(g=>[g.id,g.name]),d.greenhouseId)+label('bunches','Сколько веток срезано?',d.bunches,'inputmode="numeric" placeholder="Например, 42"')+`<div class="notice">Вес: UNKNOWN. Полевой отчёт сохранится отдельно от чеков депо. Связать их можно позже.</div>`;
 if(kind.startsWith('inventory-'))fields=select('stockId','Товар · единица · место',s.stock.map(x=>[x.id,`${x.name} · ${x.unit} · ${x.place}`]),d.stockId)+label('quantity','Количество в указанной единице',d.quantity,'inputmode="decimal"')+(kind==='inventory-transfer'?select('toPlace','Куда переместить',s.daily.greenhouses.map(g=>[g.name,g.name]),d.toPlace):'')+`<p class="note">${kind==='inventory-arrival'?'Физический приход не создаёт долг, оплату или стоимость. При UNKNOWN начальном остатке новый остаток тоже UNKNOWN.':kind==='inventory-consumption'?'Внесение уменьшает известный остаток только после отдельного подтверждения.':'Перемещение сохраняет общий объём, без конвертации единиц. UNKNOWN остаток назначения не превращается в известный.'}</p>`;
 if(kind==='task')fields=label('title','Что нужно сделать?',d.title)+select('place','Теплица · необязательно',s.daily.greenhouses.map(g=>[g.name,g.name]),d.place,'Не указана')+label('when','Когда · необязательно',d.when,'placeholder="Например, следующая неделя"')+`<p class="note">Личная задача. Работник не назначается, сообщение никому не отправляется.</p>`;
 if(kind==='worker')fields=label('title','Поручение на русском',d.title)+select('worker','Кому',s.workers.map(w=>[w.id,w.name]),d.worker)+select('place','Теплица',s.daily.greenhouses.map(g=>[g.name,g.name]),d.place)+`<details class="source-details"><summary>Текст на дари · ручной ввод</summary><label class="field">Проверенный владельцем текст<textarea class="input" name="translation" data-testid="daily-translation" lang="fa" dir="rtl">${e(d.translation||'')}</textarea></label></details><div class="notice amber">Только локальное DEMO-поручение. Автоматического перевода и отправки нет. Если дари не введён, он останется неподготовленным.</div>`;
 if(kind==='depot')fields=`<div class="notice">Добавьте фото или PDF. Произвольные документы здесь не распознаются. Заранее подготовленный DEMO-чек можно проверить отдельно.</div>${link(`${icon('camera')} Фото / документ`, 'capture/photo','btn primary full','depot-capture')}${link('Открыть синтетические чеки','depots','btn secondary full','depot-records')}`;
 const dateField=kind==='task'||kind==='depot'?'':label('date','Дата события',date,'type="date"')+`<p class="note" data-testid="date-assumption">${d.dateAssumed===false?'Дата указана владельцем.':'Предположение: сегодня, 9 октября 2026. Проверьте или измените дату.'} ${['expense','payment','obligation'].includes(kind)?'TRY предложена как рабочая валюта; можно изменить.':''}</p>`;
 return `<div class="daily-form">${Header(action?'Уточнить одно действие':actionTitle(kind),'Только synthetic DEMO',true)}<form id="daily-form" data-r3-form="daily-${e(kind)}" data-kind="${e(kind)}" data-key="${e(key)}" data-edit-id="${e(editId||'')}"><section class="card">${fields}${dateField}${kind==='depot'?'':`<p id="daily-form-error" class="notice red" hidden></p>${btn(kind==='task'?'Сохранить личную задачу':kind==='worker'?'Проверил поручение · назначить в DEMO':action?'Сохранить уточнение':'Сохранить источник · проверить','daily-save','primary full','daily-save','type="button"')}`}</section></form><p class="note">Оригиналы, черновики и подтверждения хранятся только в этом браузере. Никаких бизнес-запросов.</p></div>`;
}
function actionFacts(s,a){
 const i=a.input;
 if(['expense','payment','obligation'].includes(a.kind))return fact('Назначение',i.purpose||'UNKNOWN')+fact('Сумма',i.amountMinor?formatMinor(i.amountMinor,i.currency):'UNKNOWN')+fact('Контрагент',i.party||'Не указан · необязательно для расхода')+(a.kind==='payment'?fact('Счёт',s.daily.accounts.find(x=>x.id===i.accountId)?.name||'Нужно выбрать')+fact('Погашение',s.daily.obligations.find(x=>x.id===i.obligationId)?.purpose||'Без связи с долгом'):'');
 if(a.kind==='harvest')return fact('Теплица',gh(s,i.greenhouseId))+fact('Срезано',`${i.bunches||'UNKNOWN'} веток`)+fact('Вес','UNKNOWN')+fact('Связь с чеком','Нет · можно связать позже');
 if(a.kind.startsWith('inventory-')){const item=s.stock.find(x=>x.id===i.stockId);return fact('Материал',item?.name||'UNKNOWN')+fact('Откуда',item?.place||'UNKNOWN')+fact('Количество',`${i.quantity||'UNKNOWN'} ${item?.unit||''}`)+(i.toPlace?fact('Куда',i.toPlace):'');}
 if(a.kind==='harvest-link')return fact('Срез',i.reportId)+fact('Чек',i.receiptId)+fact('Вес / выручка по теплицам','Не распределяются автоматически');
 return '';
}
export function dailyReview(s,id){
 const a=s.daily.actions.find(a=>a.id===id);if(!a)return EmptyState('Запись не найдена','Вернитесь в раздел.');
 const src=s.daily.sources.find(x=>x.id===a.sourceId), confirmed=a.status==='confirmed';
 const effect={expense:'Будет сохранён расход. Денежная выплата и кредиторская задолженность не создаются.',payment:'Будет сохранён один денежный платёж. Расход повторно не создаётся; выбранная связь может уменьшить один долг.',obligation:'Будет сохранено обязательство. Оплаты и автоматического расхода нет.',harvest:'Будет сохранён полевой отчёт. Килограммы, продажа и чек депо не создаются.','inventory-arrival':'Изменится только физический запас выбранного товара. Оплаты, долга и стоимости нет.','inventory-consumption':'Известный запас уменьшится на указанное количество. Денежные записи не меняются.','inventory-transfer':'Два связанных складских движения. Денежные записи не меняются.','harvest-link':'Будет подтверждена только связь отчёта и чека. Вес и выручка по теплицам не распределяются.'}[a.kind];
 return `<div class="daily-form">${Header(actionTitle(a.kind),'Проверка действия',true)}<section class="card"><span class="tag ${confirmed?'':'amber'}">${confirmed?'Подтверждено в DEMO':'Источник в DEMO · на проверке'}</span><h2 class="detail-title">${a.kind==='expense'?'Расход · не оплата':a.kind==='harvest'?'Полевой отчёт · не чек':actionTitle(a.kind)}</h2><dl class="fact-list">${actionFacts(s,a)}${fact('Дата',a.input.date)}${fact('Происхождение',a.provenance==='owner-correction'?'Owner correction · уточнение владельца':'Ручной ввод · кандидат')}${fact('Дата по умолчанию',a.input.dateAssumed?'Предположение, показано до сохранения':'Указана владельцем')}</dl><div class="notice">${effect}</div><section class="source-evidence"><span class="eyebrow">ОРИГИНАЛ · SYNTHETIC SOURCE</span><p data-testid="daily-original">${e(src?.raw)}</p>${src?.structuredOriginal?`<details class="source-details"><summary>Факты при сохранении источника</summary><dl class="fact-list">${Object.entries(src.structuredOriginal).filter(([k,v])=>v!==""&&k!=="raw").map(([k,v])=>fact(({purpose:"Назначение",amount:"Сумма",currency:"Валюта",date:"Дата события",greenhouseId:"ID теплицы",bunches:"Ветки",stockId:"ID материала",quantity:"Количество",toPlace:"Куда"})[k]||k,typeof v==="object"?JSON.stringify(v):v)).join("")}</dl><p class="note">Дата события при вводе: ${e(src.eventDateOriginal||"не указана")}. Дата захвата браузером: ${e(src.capturedAt||"UNKNOWN")}.</p></details>`:""}</section>${confirmed?`<div class="notice" data-testid="daily-confirmed">Подтверждено только в текущем DEMO. Повторного эффекта нет.</div>${link(['harvest','harvest-link'].includes(a.kind)?'Открыть срезы и сверку':a.kind.startsWith('inventory-')?'Открыть склад':'Открыть финансы',['harvest','harvest-link'].includes(a.kind)?'reconcile':a.kind.startsWith('inventory-')?'inventory':'finance/overview','btn primary full','daily-result-open')}`:`${a.clarifications.length?`<div class="notice amber" data-testid="daily-clarifications"><strong>Нужно короткое уточнение</strong><ul>${a.clarifications.map(x=>`<li>${e(x)}</li>`).join('')}</ul></div>`:''}${a.canConfirm?btn('Подтвердить только это действие','daily-confirm:'+id,'primary full','daily-confirm',`data-revision="${a.revision}"`):''}${a.kind!=='harvest-link'?link('Уточнить факты',`quick/${a.kind}/${id}`,'btn secondary full','daily-edit'):''}`}</section></div>`;
}
export function depotList(s){return `${Header('Чеки депо','1 сентября — 9 октября 2026 · TRY',true)}${contextualActions([['Добавить чек','quick/depot','depot-add'],['Срезы и сверка','reconcile','depot-reconcile']])}<div class="daily-list">${[...s.daily.receipts].reverse().map(r=>link(`<span class="provenance">SOURCE FACT · SYNTHETIC</span><h3>${e(r.party)}</h3><p>${e(r.date)} · ${number(r.adet)} ADET · ${number(r.netKg,3)} кг</p><span class="record-value">${minor(r.totalMinor)}</span><p>${r.greenhouseId?e(gh(s,r.greenhouseId)):'Смешанная партия · kg / выручка по теплицам UNKNOWN'}</p>`,`depot/${r.id}`,'daily-record',`depot-${r.id}`)).join('')}</div><p class="note">Alacak — баланс дебиторской задолженности. Его нельзя складывать с выручкой или принимать за платёж.</p>`;}
export function depotDetail(s,id){
 const r=s.daily.receipts.find(x=>x.id===id);if(!r)return EmptyState('Чек не найден','Вернитесь к списку.');
 const src=s.daily.sources.find(x=>x.id===r.sourceId);
 return `<div class="detail-layout">${Header('Чек депо',r.date+' · Synthetic DEMO',true)}<section class="card"><span class="eyebrow">${e(r.party)}</span><h2 class="detail-title">${minor(r.totalMinor)}</h2><div class="compact-summary"><div><span class="label">ADET · ветки</span><strong>${number(r.adet)}</strong></div><div><span class="label">Вес нетто</span><strong>${number(r.netKg,3)} кг</strong></div></div>${r.originalAdet?`<div class="notice amber"><span class="provenance">OWNER CORRECTION</span><p>В оригинале: ${e(r.originalAdet)}. Владелец подтвердил ${r.adet} ADET и ${e(gh(s,r.greenhouseId))}. Другая цифра не входит в аналитику.</p></div>`:''}<p class="list-section-label">Исходные строки · не объединены</p>${r.lines.map((l,index)=>`<div class="depot-line" data-testid="depot-line"><div class="line"><strong>Строка ${index+1} · ${e(l.quality)}</strong><strong>${minor(l.amountMinor)}</strong></div><p>ADET ${l.adet==null?"UNKNOWN":number(l.adet)} · ${number(l.netKg,3)} кг × ${minor(l.priceMinor)}/кг</p><span class="provenance">SOURCE FACT · исходное качество</span></div>`).join('')}<dl class="fact-list">${fact('Итого по чеку',minor(r.totalMinor))}${fact('Rolling Alacak',minor(r.rollingAlacakMinor))}${fact('Деньги получены','Не определяется по этому чеку')}</dl><p class="note">Классы I / II / III в этих DEMO-документах не являются универсальным правилом качества для других депо.</p>${r.allocations.length?`<div class="notice amber"><span class="provenance">DERIVED ESTIMATE · подтверждённая оценка</span><p>${e(r.allocationMethod)}</p>${r.allocations.map(a=>`<p>${e(gh(s,a.greenhouseId))}: ${a.bunches} веток · кг UNKNOWN · выручка UNKNOWN</p>`).join('')}</div>`:''}<section class="source-evidence"><span class="eyebrow">ОРИГИНАЛ · SYNTHETIC</span><p>${e(src?.raw||'Синтетический документ, сохранённые строки выше.')}</p></section>${link('Связать с полевым отчётом','reconcile','btn secondary full','depot-link-open')}</section></div>`;
}
export function reconcile(s){return `${Header('Срезы и сверка','Отчёты отдельно от чеков депо',true)}${contextualActions([['Записать срез','quick/harvest','reconcile-cut'],['Чеки депо','depots','reconcile-depots']])}<div class="notice">Одинаковая дата — только кандидат связи. Вес, качество и выручка не выводятся из количества срезанных веток.</div><div class="daily-list">${[...s.daily.fieldReports].reverse().map(r=>`<section class="daily-record"><span class="provenance">SOURCE FACT · полевой отчёт</span><h3>${e(gh(s,r.greenhouseId))} · ${number(r.bunches)} веток</h3><p>${r.date} · вес UNKNOWN</p>${r.receiptId?`<p class="note">Связь подтверждена владельцем</p>${link('Открыть связанный чек',`depot/${r.receiptId}`,'btn secondary full',`linked-${r.id}`)}`:`<div class="notice amber">Не связан с чеком</div>${receiptCandidates(s,r.id).length?`<p class="note">Совпали даты. Это не доказательство связи.</p>${receiptCandidates(s,r.id).map(c=>btn(e(c.label),`daily-link:${r.id}:${c.receiptId}`,'secondary full',`link-${r.id}-${c.receiptId}`)).join('')}`:'<p class="note">Чеков той же даты пока нет.</p>'}<details class="source-details"><summary>Выбрать чек другой даты</summary>${s.daily.receipts.filter(x=>x.date!==r.date).map(x=>btn(`${e(x.date)} · ${number(x.adet)} ADET`,`daily-link:${r.id}:${x.id}`,'secondary full')).join('')}</details>`}</section>`).join('')}</div>`;}
export function dailyMovementList(s){return `<section class="card"><h2>Денежные события</h2>${[...s.daily.payments].reverse().map(p=>`<div class="timeline-row"><div class="summary-pair"><strong>${e(p.purpose)}</strong><strong>${p.direction==='in'?'+':'−'}${minor(p.amountMinor)}</strong></div><p>${e(p.date)} · ${e(s.daily.accounts.find(a=>a.id===p.accountId)?.name||'DEMO счёт')}</p><span class="provenance">${p.category==='advance'?'АВАНС · не второй расход':p.category==='loan-principal'?'ТЕЛО ЗАЙМА · не операционный расход':'SOURCE FACT · сообщение DEMO'}</span></div>`).join('')}</section><section class="card"><h2>Расчёт оплаты труда</h2>${s.daily.salarySettlements.map(x=>`<p class="note">${e(x.party)}: ${x.paymentIds.map(id=>minor(s.daily.payments.find(p=>p.id===id).amountMinor)).join(' + ')} = ${minor(x.totalMinor)}.</p><div class="notice">Три денежных события. Общий расчёт не является четвёртым платежом.</div>`).join('')}</section><section class="card"><h2>Позднее уточнение долга</h2>${s.daily.supplierClarifications.map(x=>`<p class="note">${x.date}: остаток ${minor(x.remainingMinor)} по существующей поставке. Новый приход и новый платёж не создаются.</p>`).join('')}</section>`;}
export function invoiceNotice(s){return `<section class="card"><div class="card-header"><h2>Документ без прихода</h2><span class="tag amber">UNKNOWN</span></div>${s.daily.invoices.map(i=>`<h3>${e(i.product)}</h3><p class="note">Счёт от ${i.date}. Количество, единица, стоимость и физическое прибытие не подтверждены. В остатки не добавлено.</p>`).join('')}</section>`;}
